#include <bits/stdc++.h>
using namespace std;

long long trailingZeros(long long n) {
    long long result = 0;
    while (n > 0) {
        n /= 5;
        result += n;
    }
    return result;
}

long long lowerBound(long long target) {
    long long left = 0, right = 5 * (target + 1);
    while (left < right) {
        long long mid = left + (right - left) / 2;
        if (trailingZeros(mid) >= target)
            right = mid;
        else
            left = mid + 1;
    }
    return left;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long m;
    cin >> m;

    long long first = lowerBound(m);
    long long last = lowerBound(m + 1);

    cout << last - first << '\n';
    for (long long i = first; i < last; ++i)
        cout << i << ' ';

    return 0;
}

